/** Addresses are stored and compared lowercased, so spelling of case never splits an account. */
export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

/**
 * Addresses are matched case-insensitively. Rows written before normalization
 * still resolve, because the comparison lowercases the stored value too.
