/**
 * Workspace URL for a display name. Reserved and colliding slugs are suffixed
 * by `uniqueSlug`; a result that is empty or shorter than the minimum is never
 * used — the slug falls back to `workspace` (still suffixed when taken).
 */
async function workspaceSlug(displayName: string): Promise<string> {
  const base = slugify(displayName);
  const seed = base.length >= SLUG_MIN_LENGTH ? base : "workspace";
  const taken = await orgRepo.listTakenOrgSlugs(seed);
  return uniqueSlug(seed, taken);
}

/** `<name>'s workspace`, shortened on the name side until it fits the org name limit. */
function workspaceName(displayName: string): string {
  const chars = Array.from(displayName);
  while (
    chars.length > 0 &&
    `${chars.join("")}${WORKSPACE_SUFFIX}`.length > ORG_NAME_MAX
  ) {
    chars.pop();
  }
  return `${chars.join("")}${WORKSPACE_SUFFIX}`;
}

